TypeScript example:

interface InvocationFacade {
  startInvocation(prompt: string, metadata?: Record<string,string>): InvocationHandle;
  emitFragment(handle: InvocationHandle, fragment: { type: string; body: string | object; }): Promise<void>;
  callTool(handle: InvocationHandle, toolName: string, input: object): Promise<ReplayHandle>;
  finishInvocation(handle: InvocationHandle, resultMeta?: object): Promise<void>;
  replay(replayToken: string, options?: { mode: 'dry-run' | 'replay' }): Promise<ReplayResult>;
}

// usage sketch
const fac = new InvocationFacadeImpl();
const h = fac.startInvocation('Summarize meeting notes');
await fac.emitFragment(h, { type: 'tokens', body: 'Thanks everyone for...' });
const replay = await fac.callTool(h, 'calendar.create_event', { title: 'Follow up', time: '2026-03-01T10:00Z' });
await fac.finishInvocation(h);
// persist replay.token for later deterministic replay
await fac.replay(replay.token, { mode: 'dry-run' });
